try { const x = mix(Function.prototype); if (Array.prototype.isPrototypeOf(x)) out("  yes", `${typeof x} ${t(() => x.length)} ${t(() => x.name)} ${t(() => x.size)} ${t(() => x.message)} ${t(() => x.getTime)} ${t(() => typeof (x + 1))} ${t(() => x[0])}`); else out("  no", `${typeof x} ${t(() => x.length)} ${t(() => x.name)} ${t(() => x.size)} ${t(() => x.message)} ${t(() => x.getTime)} ${t(() => typeof (x + 1))} ${t(() => x[0])}`); } catch (error) { out("  neither", error.constructor.name); }
